-- Brazil deep-dive page translations: page fields, stats, cards,
-- lifecycle card + statuses, steps, portal.

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'es', 'Compensación multicapa (estatal + municipal + federal)', 'Esta página de análisis refleja la orientación técnica disponible públicamente a julio de 2026 y se proporciona a título informativo general, no como asesoramiento legal o fiscal. La Nota Técnica 2025.002-RTC sigue revisándose durante la transición de la reforma fiscal, y los requisitos estatales/municipales varían — confirme los requisitos actuales directamente con la SEFAZ, la Receita Federal o un asesor fiscal brasileño antes de construir una integración.', 'El sistema NF-e de Brasil funciona desde mediados de la década de 2000 con una adopción casi universal — la historia actual es la reforma del impuesto al consumo que se está incorporando a la infraestructura existente.', 'La profundidad del XML de Brasil es genuinamente inusual — se trata de una estructura mucho más granular que la mayoría de los estándares europeos de facturación electrónica.', 'Brasil no opera un único sistema de facturación electrónica — opera varios, divididos por tipo de transacción y nivel de gobierno, cada uno con sus propias particularidades.', 'Dado que la reforma fiscal se superpone a un sistema existente y maduro, "estar preparado" aquí significa principalmente actualizar lo que ya opera, no construir desde cero.', 'En Brasil, el rechazo suele ser el riesgo práctico más agudo — una factura bloqueada detiene el movimiento de mercancías, lo que con frecuencia importa más que la multa en sí.' FROM countries WHERE name_en = 'Brazil';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'de', 'Mehrschichtiges Clearing (bundesstaatlich + kommunal + föderal)', 'Diese Länderanalyse spiegelt öffentlich verfügbare technische Hinweise mit Stand Juli 2026 wider und dient der allgemeinen Information, nicht als Rechts- oder Steuerberatung. Die Technische Mitteilung 2025.002-RTC wird während des Steuerreform-Übergangs weiterhin überarbeitet, und die bundesstaatlichen/kommunalen Anforderungen variieren — bestätigen Sie aktuelle Anforderungen direkt bei der SEFAZ, der Receita Federal oder einem brasilianischen Steuerberater, bevor Sie eine Integration aufbauen.', 'Brasiliens NF-e-System läuft seit Mitte der 2000er-Jahre mit nahezu universeller Verbreitung — die aktuelle Geschichte ist die Verbrauchsteuerreform, die in die bestehende Infrastruktur eingebettet wird.', 'Brasiliens XML-Tiefe ist wirklich ungewöhnlich — dies ist eine weitaus granularere Struktur als die meisten europäischen E-Rechnungsstandards.', 'Brasilien betreibt nicht ein einziges E-Rechnungssystem — es betreibt mehrere, aufgeteilt nach Transaktionstyp und Regierungsebene, jedes mit seinen eigenen Eigenheiten.', 'Da die Steuerreform auf einem bereits ausgereiften bestehenden System aufbaut, bedeutet "Vorbereitung" hier vor allem die Aktualisierung dessen, was Sie bereits betreiben, nicht den Aufbau von Grund auf.', 'In Brasilien ist Ablehnung oft das schärfere praktische Risiko — eine blockierte Rechnung stoppt den Warenverkehr, was häufig schwerer wiegt als die Geldstrafe selbst.' FROM countries WHERE name_en = 'Brazil';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'fr', 'Contrôle multicouche (étatique + municipal + fédéral)', 'Cette analyse par pays reflète les directives techniques publiquement disponibles à juillet 2026 et est fournie à titre d''information générale, non comme un conseil juridique ou fiscal. La note technique 2025.002-RTC continue d''être révisée tout au long de la transition de la réforme fiscale, et les exigences étatiques/municipales varient — confirmez les exigences actuelles directement auprès de la SEFAZ, de la Receita Federal ou d''un conseiller fiscal brésilien avant de construire une intégration.', 'Le système NF-e du Brésil fonctionne depuis le milieu des années 2000 avec une adoption quasi universelle — l''actualité aujourd''hui est la réforme de la taxe à la consommation qui se superpose à l''infrastructure existante.', 'La profondeur du XML brésilien est véritablement inhabituelle — il s''agit d''une structure bien plus granulaire que la plupart des normes européennes de facturation électronique.', 'Le Brésil n''exploite pas un système unique de facturation électronique — il en exploite plusieurs, répartis par type de transaction et niveau de gouvernement, chacun avec ses propres particularités.', 'Comme la réforme fiscale se superpose à un système existant mature, « se préparer » ici signifie surtout mettre à niveau ce que vous exploitez déjà, pas construire à partir de zéro.', 'Au Brésil, le rejet est souvent le risque pratique le plus aigu — une facture bloquée arrête le mouvement des marchandises, ce qui compte souvent plus que l''amende elle-même.' FROM countries WHERE name_en = 'Brazil';

