INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Estructura del documento', '[["Documento legal", "El XML firmado — no el DANFE impreso"], ["Profundidad de la estructura", "500+ etiquetas estructuradas, 400+ reglas de validación"], ["Códigos de modelo", "Modelo 55 (NF-e), Modelo 65 (NFC-e)"]]', 'El DANFE contiene menos del 10% de los datos del XML — trate cualquier proceso de AP que solo lea el DANFE como una re-introducción manual de información que ya existe en forma estructurada, y que probablemente omite detalles fiscales que afectan a la recuperación del crédito fiscal.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Brazil' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Dokumentstruktur', '[["Rechtsdokument", "Das signierte XML — nicht das gedruckte DANFE"], ["Strukturtiefe", "500+ strukturierte Tags, 400+ Validierungsregeln"], ["Modellcodes", "Modell 55 (NF-e), Modell 65 (NFC-e)"]]', 'Das DANFE enthält weniger als 10 % der XML-Daten — betrachten Sie jeden AP-Prozess, der nur das DANFE liest, als manuelle Neueingabe von Informationen, die bereits in strukturierter Form vorliegen, und der wahrscheinlich Steuerdetails übersieht, die die Vorsteuerrückgewinnung betreffen.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Brazil' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Structure du document', '[["Document légal", "Le XML signé — pas le DANFE imprimé"], ["Profondeur de structure", "500+ balises structurées, 400+ règles de validation"], ["Codes de modèle", "Modèle 55 (NF-e), Modèle 65 (NFC-e)"]]', 'Le DANFE contient moins de 10 % des données du XML — considérez tout processus AP qui ne lit que le DANFE comme une resaisie manuelle d''informations qui existent déjà sous forme structurée, et qui manque probablement des détails fiscaux affectant la récupération du crédit de TVA en amont.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Brazil' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'La clave de acceso de 44 dígitos', '[["Nombre", "Chave de acesso"], ["Alcance", "Única en todo Brasil, en todo momento"], ["Especificación que la rige", "SEFAZ Nota Técnica 2011/004"]]', 'Esta única clave es todo lo que necesita para verificar la autenticidad de una NF-e, comprobar si ha sido cancelada o recuperar el XML completo directamente de la SEFAZ — trátela como la referencia universal para cualquier factura brasileña.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Brazil' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Der 44-stellige Zugangsschlüssel', '[["Name", "Chave de acesso"], ["Umfang", "Eindeutig in ganz Brasilien, über die gesamte Zeit"], ["Maßgebliche Spezifikation", "SEFAZ Nota Técnica 2011/004"]]', 'Dieser einzelne Schlüssel ist alles, was Sie benötigen, um die Echtheit einer NF-e zu überprüfen, festzustellen, ob sie storniert wurde, oder das vollständige XML direkt von der SEFAZ abzurufen — betrachten Sie ihn als universelle Referenz für jede brasilianische Rechnung.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Brazil' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'La clé d''accès à 44 chiffres', '[["Nom", "Chave de acesso"], ["Portée", "Unique dans tout le Brésil, à travers le temps"], ["Spécification régissante", "SEFAZ Nota Técnica 2011/004"]]', 'Cette clé unique est tout ce dont vous avez besoin pour vérifier l''authenticité d''une NF-e, vérifier si elle a été annulée, ou récupérer le XML complet directement auprès de la SEFAZ — considérez-la comme la référence universelle pour toute facture brésilienne.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Brazil' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Firma digital', '[["Tipos de certificado", "A1 (basado en software) o A3 (token de hardware)"], ["Acreditación", "Autoridad certificadora acreditada por ICP-Brasil"]]', 'Ambos tipos de certificado son válidos — A1 se adapta a la emisión automatizada de gran volumen, A3 se adapta a escenarios de menor volumen o mayor seguridad, pero confirme cuál admite su integración ERP específica.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Brazil' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Digitale Signatur', '[["Zertifikatstypen", "A1 (softwarebasiert) oder A3 (Hardware-Token)"], ["Akkreditierung", "Von ICP-Brasil akkreditierte Zertifizierungsstelle"]]', 'Beide Zertifikatstypen sind gültig — A1 eignet sich für automatisierte Hochvolumen-Ausstellung, A3 für Szenarien mit geringerem Volumen oder höherer Sicherheit, aber bestätigen Sie, welches Ihre spezifische ERP-Integration unterstützt.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Brazil' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Signature numérique', '[["Types de certificat", "A1 (basé sur logiciel) ou A3 (jeton matériel)"], ["Accréditation", "Autorité de certification accréditée ICP-Brasil"]]', 'Les deux types de certificat sont valides — A1 convient à l''émission automatisée à haut volume, A3 convient aux scénarios à volume plus faible ou à sécurité renforcée, mais confirmez lequel votre intégration ERP spécifique prend en charge.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Brazil' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Nuevos campos de la reforma fiscal (NT 2025.002-RTC)', '[["Nuevos grupos", "Grupos de datos IBS, CBS e IS (Impuesto Selectivo)"], ["Nuevos códigos fiscales", "Códigos CST específicos para los tres nuevos impuestos"], ["Nuevos tipos de documento", "Notas de Débito y Crédito formales dentro del modelo 55"]]', 'Las Notas de Débito y Crédito son un instrumento genuinamente nuevo, no uno reutilizado — pero explícitamente no pueden usarse para ajustar el ICMS o IPI heredados a menos que esa legislación se modifique por separado.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Brazil' AND dc.section = 'file_format' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Neue Steuerreformfelder (NT 2025.002-RTC)', '[["Neue Gruppen", "IBS-, CBS- und IS-Datengruppen (Selektivsteuer)"], ["Neue Steuercodes", "CST-Codes speziell für die drei neuen Steuern"], ["Neue Dokumenttypen", "Formale Lastschriften und Gutschriften innerhalb von Modell 55"]]', 'Last- und Gutschriften sind ein wirklich neues Instrument, kein umfunktioniertes altes — sie können jedoch ausdrücklich nicht zur Anpassung der Alt-ICMS oder -IPI verwendet werden, sofern diese Gesetzgebung nicht separat geändert wird.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Brazil' AND dc.section = 'file_format' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Nouveaux champs de la réforme fiscale (NT 2025.002-RTC)', '[["Nouveaux groupes", "Groupes de données IBS, CBS et IS (taxe sélective)"], ["Nouveaux codes fiscaux", "Codes CST spécifiques aux trois nouvelles taxes"], ["Nouveaux types de documents", "Notes de débit et de crédit formelles au sein du modèle 55"]]', 'Les notes de débit et de crédit sont un instrument véritablement nouveau, pas un ancien réutilisé — mais elles ne peuvent explicitement pas être utilisées pour ajuster les anciens ICMS ou IPI sauf modification législative distincte.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Brazil' AND dc.section = 'file_format' AND dc.sort_order = 3;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'La familia de documentos', '[["NF-e", "Mercancías — SEFAZ a nivel estatal"], ["NFC-e", "Recibos minoristas/de consumidor — SEFAZ a nivel estatal"], ["CT-e", "Documentos de transporte — SEFAZ a nivel estatal"], ["NFS-e", "Servicios — nivel municipal (5.000+ variaciones)"]]', 'Qué sistema se aplica depende enteramente de lo que esté facturando — mercancías, transporte y venta minorista corresponden al estado; los servicios corresponden al municipio, y los requisitos municipales varían significativamente.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Brazil' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Die Dokumentenfamilie', '[["NF-e", "Waren — SEFAZ auf Bundesstaatenebene"], ["NFC-e", "Einzelhandels-/Verbraucherquittungen — SEFAZ auf Bundesstaatenebene"], ["CT-e", "Transportdokumente — SEFAZ auf Bundesstaatenebene"], ["NFS-e", "Dienstleistungen — kommunale Ebene (5.000+ Varianten)"]]', 'Welches System gilt, hängt vollständig davon ab, was Sie fakturieren — Waren, Transport und Einzelhandel liegen beim Bundesstaat; Dienstleistungen liegen bei der Gemeinde, und die kommunalen Anforderungen variieren erheblich.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Brazil' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'La famille de documents', '[["NF-e", "Marchandises — SEFAZ au niveau étatique"], ["NFC-e", "Reçus de détail/consommateur — SEFAZ au niveau étatique"], ["CT-e", "Documents de transport — SEFAZ au niveau étatique"], ["NFS-e", "Services — niveau municipal (5 000+ variantes)"]]', 'Le système applicable dépend entièrement de ce que vous facturez — marchandises, transport et vente au détail relèvent de l''État ; les services relèvent de la municipalité, et les exigences municipales varient considérablement.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Brazil' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'La fragmentación del NFS-e, y la solución en curso', '[["Estado actual", "Cada Prefeitura (municipio) establece sus propios requisitos"], ["Estándar nacional", "SNNFS-e (Sistema Nacional da Nota Fiscal de Serviços Eletrônica)"], ["Componentes", "Portal de envío centralizado + repositorio NDE (Entorno Nacional de Datos)"]]', 'La adopción del SNNFS-e es gradual y aún no obligatoria en todas partes — compruebe el estado actual de su municipio específico en lugar de asumir que la estandarización nacional ya se ha producido.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Brazil' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Die NFS-e-Fragmentierung und die laufende Lösung', '[["Aktueller Stand", "Jede Prefeitura (Gemeinde) legt ihre eigenen Anforderungen fest"], ["Nationaler Standard", "SNNFS-e (Sistema Nacional da Nota Fiscal de Serviços Eletrônica)"], ["Komponenten", "Zentralisiertes Einreichungsportal + NDE-Repository (National Data Environment)"]]', 'Die SNNFS-e-Einführung erfolgt schrittweise und ist noch nicht überall verpflichtend — prüfen Sie den aktuellen Status Ihrer spezifischen Gemeinde, statt anzunehmen, dass die nationale Standardisierung bereits erfolgt ist.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Brazil' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'La fragmentation du NFS-e, et la solution en cours', '[["État actuel", "Chaque Prefeitura (municipalité) fixe ses propres exigences"], ["Norme nationale", "SNNFS-e (Sistema Nacional da Nota Fiscal de Serviços Eletrônica)"], ["Composants", "Portail de soumission centralisé + dépôt NDE (National Data Environment)"]]', 'L''adoption du SNNFS-e est progressive et pas encore obligatoire partout — vérifiez le statut actuel de votre municipalité spécifique plutôt que de présumer que la normalisation nationale a déjà eu lieu.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Brazil' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Lo que viene: Pago Dividido', '[["Base legal", "Acto Administrativo Conjunto RFB/CGIBS N.º 2/2026"], ["Qué hace", "Publica documentación técnica para una Plataforma Pública de Pago Dividido"]]', 'Esta es una pieza emergente de la arquitectura de la reforma — la remesa automática de impuestos en el momento del pago — que vale la pena seguir aunque todavía no sea una obligación vigente.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Brazil' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Was kommt: Split Payment', '[["Rechtsgrundlage", "Gemeinsamer Verwaltungsakt RFB/CGIBS Nr. 2/2026"], ["Was es bewirkt", "Veröffentlicht technische Dokumentation für eine öffentliche Split-Payment-Plattform"]]', 'Dies ist ein aufkommender Baustein der Reformarchitektur — automatische Steuerabführung zum Zeitpunkt der Zahlung — der es wert ist, verfolgt zu werden, auch wenn er noch keine geltende Pflicht ist.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Brazil' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Ce qui arrive : le paiement scindé', '[["Base juridique", "Acte administratif conjoint RFB/CGIBS n° 2/2026"], ["Ce que cela fait", "Publie la documentation technique d''une plateforme publique de paiement scindé"]]', 'Il s''agit d''un élément émergent de l''architecture de la réforme — la remise automatique de la taxe au moment du paiement — qui mérite d''être suivi même s''il ne s''agit pas encore d''une obligation en vigueur.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Brazil' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT dlc.id, 'es', 'El flujo de compensación de la NF-e', NULL, 'La NF-e también se transmite al repositorio nacional de la Receita Federal do Brasil (Ambiente Nacional) — un respaldo a nivel federal que existe junto con la autorización a nivel estatal.' FROM deep_dive_lifecycle_cards dlc JOIN countries c ON c.id = dlc.country_id WHERE c.name_en = 'Brazil';
INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT dlc.id, 'de', 'Der NF-e-Clearing-Ablauf', NULL, 'Die NF-e wird ebenfalls an das nationale Repository der Receita Federal do Brasil (Ambiente Nacional) übermittelt — eine föderale Absicherung, die neben der bundesstaatlichen Autorisierung besteht.' FROM deep_dive_lifecycle_cards dlc JOIN countries c ON c.id = dlc.country_id WHERE c.name_en = 'Brazil';
INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT dlc.id, 'fr', 'Le flux de contrôle de la NF-e', NULL, 'La NF-e est également transmise au référentiel national de la Receita Federal do Brasil (Ambiente Nacional) — une sauvegarde au niveau fédéral qui existe parallèlement à l''autorisation au niveau étatique.' FROM deep_dive_lifecycle_cards dlc JOIN countries c ON c.id = dlc.country_id WHERE c.name_en = 'Brazil';

