INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Obtenga un certificado digital ICP-Brasil', 'Elija A1 o A3 según su volumen e infraestructura, de una autoridad certificadora acreditada — esto es necesario antes de poder firmar una sola NF-e.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Brazil' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Beschaffen Sie ein digitales ICP-Brasil-Zertifikat', 'Wählen Sie je nach Volumen und Infrastruktur A1 oder A3 von einer akkreditierten Zertifizierungsstelle — dies ist erforderlich, bevor Sie auch nur eine einzige NF-e signieren können.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Brazil' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Obtenez un certificat numérique ICP-Brasil', 'Choisissez A1 ou A3 selon votre volume et votre infrastructure, auprès d''une autorité de certification accréditée — ceci est requis avant de pouvoir signer la moindre NF-e.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Brazil' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Configure su establecimiento fiscal', 'Configure el certificado, el entorno, la versión de NF-e, la autoridad, la validación del esquema y el modo de contingencia por establecimiento fiscal en su ERP — se trata de una configuración genuinamente por establecimiento, no de un ajuste global único.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Brazil' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Konfigurieren Sie Ihre steuerliche Niederlassung', 'Richten Sie Zertifikat, Umgebung, NF-e-Version, Behörde, Schemavalidierung und Notfallmodus pro steuerlicher Niederlassung in Ihrem ERP ein — dies ist eine wirklich niederlassungsbezogene Konfiguration, keine einmalige globale Einstellung.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Brazil' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Configurez votre établissement fiscal', 'Configurez le certificat, l''environnement, la version NF-e, l''autorité, la validation du schéma et le mode de contingence par établissement fiscal dans votre ERP — il s''agit d''une configuration véritablement par établissement, pas d''un réglage global unique.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Brazil' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Actualice a la Nota Técnica 2025.002-RTC (versión actual)', 'Asigne los nuevos campos IBS, CBS e IS y los códigos fiscales CST actualizados en sus diseños de facturación — verifique cuidadosamente el número de versión, ya que esta nota se ha revisado varias veces durante 2025–2026.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Brazil' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Aktualisieren Sie auf die Technische Mitteilung 2025.002-RTC (aktuelle Version)', 'Ordnen Sie die neuen IBS-, CBS- und IS-Felder sowie die aktualisierten CST-Steuercodes in Ihre Rechnungslayouts ein — prüfen Sie die Versionsnummer sorgfältig, da diese Mitteilung 2025–2026 mehrfach überarbeitet wurde.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Brazil' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Mettez à jour vers la note technique 2025.002-RTC (version actuelle)', 'Associez les nouveaux champs IBS, CBS et IS ainsi que les codes fiscaux CST mis à jour dans vos formats de facturation — vérifiez attentivement le numéro de version, car cette note a été révisée plusieurs fois en 2025-2026.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Brazil' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Pruebe en el entorno de homologación de la SEFAZ', 'Use los mismos certificados que en producción, apuntando a servidores de prueba, para validar sus nuevos campos de la reforma fiscal antes de que afecten a facturas reales.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Brazil' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Testen Sie in der Homologationsumgebung der SEFAZ', 'Verwenden Sie dieselben Zertifikate wie in der Produktion, gerichtet auf Testserver, um Ihre neuen Steuerreformfelder zu validieren, bevor sie echte Rechnungen betreffen.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Brazil' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Testez dans l''environnement d''homologation de la SEFAZ', 'Utilisez les mêmes certificats qu''en production, pointés vers des serveurs de test, pour valider vos nouveaux champs de réforme fiscale avant qu''ils n''affectent de vraies factures.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Brazil' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Construya los nuevos flujos de trabajo de Notas de Débito/Crédito', 'Implemente los instrumentos formalizados de Notas de Débito y Crédito del modelo 55 para los ajustes de CBS/IBS — recordando que no pueden usarse para correcciones heredadas de ICMS/IPI sin un cambio legislativo separado.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Brazil' AND ds.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Bauen Sie die neuen Last-/Gutschriften-Workflows auf', 'Implementieren Sie die formalisierten Modell-55-Last- und Gutschrifteninstrumente für CBS/IBS-Anpassungen — denken Sie daran, dass sie ohne separate Gesetzesänderung nicht für Alt-ICMS-/IPI-Korrekturen verwendet werden können.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Brazil' AND ds.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Construisez les nouveaux flux de travail de notes de débit/crédit', 'Mettez en œuvre les instruments formalisés de notes de débit et de crédit du modèle 55 pour les ajustements CBS/IBS — en gardant à l''esprit qu''ils ne peuvent pas être utilisés pour des corrections ICMS/IPI héritées sans modification législative distincte.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Brazil' AND ds.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Compruebe los requisitos específicos del municipio de su NFS-e', 'Si emite facturas de servicios, confirme por separado la especificación NFS-e actual de su municipio y el estado de adopción del SNNFS-e — no asuma todavía uniformidad nacional.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Brazil' AND ds.sort_order = 5;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Prüfen Sie die spezifischen Anforderungen Ihrer NFS-e-Gemeinde', 'Wenn Sie Dienstleistungsrechnungen ausstellen, bestätigen Sie separat die aktuelle NFS-e-Spezifikation und den SNNFS-e-Einführungsstatus Ihrer Gemeinde — gehen Sie noch nicht von nationaler Einheitlichkeit aus.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Brazil' AND ds.sort_order = 5;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Vérifiez les exigences spécifiques de votre municipalité NFS-e', 'Si vous émettez des factures de services, confirmez séparément la spécification NFS-e actuelle de votre municipalité et le statut d''adoption du SNNFS-e — ne présumez pas encore d''une uniformité nationale.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Brazil' AND ds.sort_order = 5;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Confirme el calendario de transición de su régimen', 'Las empresas de Simples Nacional y MEI generalmente tienen una transición extendida (hasta 2027) en comparación con los contribuyentes del Régimen Normal/General — verifique cuál se aplica a usted antes de asumir los mismos plazos.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Brazil' AND ds.sort_order = 6;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Bestätigen Sie den Übergangszeitplan Ihres Steuersystems', 'Simples-Nacional- und MEI-Unternehmen haben im Allgemeinen einen verlängerten Übergang (bis 2027) im Vergleich zu Steuerpflichtigen des normalen/allgemeinen Steuersystems — prüfen Sie, welcher für Sie gilt, bevor Sie dieselben Fristen annehmen.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Brazil' AND ds.sort_order = 6;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Confirmez le calendrier de transition de votre régime', 'Les entreprises Simples Nacional et MEI bénéficient généralement d''une transition prolongée (jusqu''en 2027) par rapport aux contribuables du régime normal/général — vérifiez lequel s''applique à vous avant de présumer des mêmes échéances.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Brazil' AND ds.sort_order = 6;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', '🚧 El rechazo como sanción operativa', NULL, NULL, 'A partir del 3 de agosto de 2026, los datos IBS/CBS faltantes o inconsistentes corren el riesgo de rechazo directo del documento en producción — una NF-e rechazada no puede usarse para enviar mercancías, lo que convierte esto en un riesgo de interrupción de la cadena de suministro tanto como de cumplimiento.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Brazil' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', '🚧 Ablehnung als operative Sanktion', NULL, NULL, 'Ab dem 3. August 2026 riskieren fehlende oder inkonsistente IBS/CBS-Daten eine direkte Ablehnung des Dokuments in der Produktion — eine abgelehnte NF-e kann nicht zum Versand von Waren verwendet werden, was dies ebenso zu einem Lieferkettenrisiko wie zu einem Compliance-Risiko macht.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Brazil' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', '🚧 Le rejet comme sanction opérationnelle', NULL, NULL, 'À partir du 3 août 2026, des données IBS/CBS manquantes ou incohérentes risquent un rejet pur et simple du document en production — une NF-e rejetée ne peut pas être utilisée pour expédier des marchandises, ce qui en fait autant un risque de perturbation de la chaîne d''approvisionnement qu''un risque de conformité.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Brazil' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', '🌱 El aterrizaje suave fue informal, no una exención legal', NULL, NULL, 'Incluso durante el período de gracia de enero a abril de 2026, en el que los campos IBS/CBS faltantes no provocaban rechazo, la obligación legal subyacente de incluir esos datos ya estaba vigente — las empresas que la omitieron por completo aún enfrentan exposición a sanciones de forma retroactiva.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Brazil' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', '🌱 Die sanfte Landung war informell, keine gesetzliche Befreiung', NULL, NULL, 'Selbst während der Übergangsfrist von Januar bis April 2026, in der fehlende IBS/CBS-Felder keine Ablehnung auslösten, galt die zugrunde liegende gesetzliche Pflicht zur Angabe dieser Daten bereits — Unternehmen, die sie vollständig ausließen, sind rückwirkend weiterhin einem Strafrisiko ausgesetzt.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Brazil' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', '🌱 L''atterrissage en douceur était informel, pas une exemption légale', NULL, NULL, 'Même pendant la période de grâce de janvier à avril 2026, où des champs IBS/CBS manquants n''entraînaient pas de rejet, l''obligation légale sous-jacente d''inclure ces données était déjà en vigueur — les entreprises qui l''ont complètement ignorée restent exposées à des sanctions rétroactives.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Brazil' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', '🏛️ La variación a nivel estatal añade complejidad', NULL, NULL, 'Los estados individuales pueden superponer sus propios mandatos técnicos al marco federal — Goiás, por ejemplo, exige por separado que los contribuyentes de ICMS integren los sistemas de pago (tarjetas, PIX) directamente con la emisión de NF-e/NFC-e en tiempo real.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Brazil' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', '🏛️ Bundesstaatliche Abweichungen erhöhen die Komplexität', NULL, NULL, 'Einzelne Bundesstaaten können ihre eigenen technischen Vorgaben auf das föderale Rahmenwerk aufsetzen — Goiás beispielsweise verlangt separat von ICMS-Steuerpflichtigen, Zahlungssysteme (Karten, PIX) in Echtzeit direkt mit der NF-e/NFC-e-Ausstellung zu integrieren.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Brazil' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', '🏛️ Les variations au niveau étatique ajoutent de la complexité', NULL, NULL, 'Certains États peuvent superposer leurs propres mandats techniques au cadre fédéral — Goiás, par exemple, exige séparément des contribuables ICMS qu''ils intègrent les systèmes de paiement (cartes, PIX) directement avec l''émission de NF-e/NFC-e en temps réel.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Brazil' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', '🌍 Proveedores extranjeros recién incluidos en el alcance', NULL, NULL, 'La reforma extiende las obligaciones de CBS/IBS a los proveedores extranjeros de servicios digitales por primera vez — anteriormente, los proveedores extranjeros generalmente no podían registrarse sin presencia local, y los servicios digitales transfronterizos a menudo caían bajo el ISS municipal.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Brazil' AND dc.section = 'penalties_related' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', '🌍 Ausländische Anbieter neu im Anwendungsbereich', NULL, NULL, 'Die Reform erweitert die CBS/IBS-Pflichten erstmals auf ausländische Anbieter digitaler Dienstleistungen — zuvor konnten sich ausländische Anbieter im Allgemeinen nicht ohne lokale Präsenz registrieren, und grenzüberschreitende digitale Dienstleistungen fielen oft stattdessen unter die kommunale ISS.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Brazil' AND dc.section = 'penalties_related' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', '🌍 Les fournisseurs étrangers nouvellement concernés', NULL, NULL, 'La réforme étend pour la première fois les obligations CBS/IBS aux fournisseurs étrangers de services numériques — auparavant, les fournisseurs étrangers ne pouvaient généralement pas s''enregistrer sans présence locale, et les services numériques transfrontaliers relevaient souvent de l''ISS municipal à la place.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Brazil' AND dc.section = 'penalties_related' AND dc.sort_order = 3;

INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT dp.id, 'es', 'Portal Nacional da NF-e (SEFAZ)' FROM deep_dive_portals dp JOIN countries c ON c.id = dp.country_id WHERE c.name_en = 'Brazil' AND dp.sort_order = 0;
